'use strict';

/**
 * @ngdoc service
 * @name nethvoiceWizardUiApp.ProvFanvilService
 * @description
 * # ProvFanvilService
 * Service in the nethvoiceWizardUiApp.
 */
angular.module('nethvoiceWizardUiApp')
  .service('ProvFanvilService', function (GenericPhoneService) {

    this.preferences = function (modelMap) {
      let preferences = GenericPhoneService.preferences(modelMap)
      if (preferences && modelMap.general.door_phone) {
        // The RTSP (video stream) password of the door phone: generated by
        // the PBX, shown and changed here. It is never the admin password of
        // the phones, which is the password of the web interface.
        preferences.items.push({
          "variable": "door_rtsp_password",
          "description": "door_phone_rtsp_password_label",
          "type": "password"
        })
      } else if (preferences) {
        preferences.items.push(GenericPhoneService.autoHeadsetItem())
      }
      return preferences
    }

    this.phonebook = function (modelMap) {
      return GenericPhoneService.phonebook(modelMap)
    }

    this.displayAndRingtones = function (modelMap) {
      return GenericPhoneService.displayAndRingtones(modelMap)
    }

    this.network = function (modelMap) {
      return GenericPhoneService.network(modelMap)
    }

    this.softKeys = function (modelMap) {
      return GenericPhoneService.softKeys(modelMap)
    }

    // Door phone values, checked again by Tancredi (422): DTMF codes of 1-16
    // characters among 0-9, A-D, * and #; relay open time of 1-600 seconds;
    // labels without control characters (a line break would add lines to
    // the device configuration)
    const DOOR_DTMF_PATTERN = /^[0-9A-Da-d*#]{1,16}$/
    const DOOR_DURATION_PATTERN = /^([1-9]|[1-9][0-9]|[1-5][0-9][0-9]|600)$/
    const DOOR_LABEL_PATTERN = /^[^\x00-\x1f\x7f]*$/

    this.lineKeys = function (modelMap) {
      let lineKeys = GenericPhoneService.lineKeys(modelMap)
      if (lineKeys && modelMap.general.door_phone) {
        // Door phones: every call button is a speed dial. Only that type is
        // listed (hiding the others would leave the type list not rendered).
        lineKeys.items[0].data.items.forEach(function (item) {
          if (item.variable == "linekey_type") {
            item.options = item.options.filter(function (option) {
              return option.value == "speed_dial"
            })
          }
          // The label is written as it is into the door phone configuration
          if (item.variable == "linekey_label") {
            item.pattern = DOOR_LABEL_PATTERN
            item.patternError = "door_phone_label_invalid"
          }
        })
        modelMap.lineKeys.hidden_types = []
      }
      return lineKeys
    }

    // Door phones: the relays, opened by a DTMF code during a call. Relay 1
    // opens with door_dtmf_code (the code the PBX sends to open the door),
    // relay 2 with door_dtmf_code_2.
    this.doorRelays = function (modelMap) {
      let count = Math.min(modelMap.general.door_relay_count || 0, 2)
      if (!count) {
        return
      }
      let items = []
      for (let relay = 1; relay <= count; relay++) {
        items.push({
          "variable": relay == 1 ? "door_dtmf_code" : "door_dtmf_code_" + relay,
          "description": "door_phone_relay_" + relay + "_dtmf_label",
          "type": "input",
          "pattern": DOOR_DTMF_PATTERN,
          "patternError": "door_phone_dtmf_invalid"
        }, {
          "variable": "door_relay_duration_" + relay,
          "description": "door_phone_relay_" + relay + "_duration_label",
          "type": "input",
          "pattern": DOOR_DURATION_PATTERN,
          "patternError": "door_phone_duration_invalid"
        })
      }
      return {
        "name": "door_phone_relays_section",
        "items": items
      }
    }

    this.expansionKeys = function (modelMap) {
      return GenericPhoneService.expansionKeys(modelMap)
    }

  })